use crate::aap::caps::kb_read;

struct Node;

const MAX_QUESTION: usize = 512;

/// Truncate to at most `max` bytes on a char boundary. A string of at most
/// `max` bytes also has at most `max` characters.
fn bound(s: String, max: usize) -> String {
    if s.len() <= max {
        return s;
    }
    let mut end = max;
    while end > 0 && !s.is_char_boundary(end) {
        end -= 1;
    }
    s[..end].to_string()
}

impl Guest for Node {
    fn run(query: ModeratedQuery) -> ConversationContext {
        let q = query.query;
        let question = bound(q.question, MAX_QUESTION);
        let knowledge: Vec<String> = kb_read::lookup(&question);
        ConversationContext {
            intent: q.intent,
            question,
            knowledge,
        }
    }
}

export!(Node);
